MAJORS = PROFILES["majors"]      # 88 个推导专业
CURATED = PROFILES["curated"]    # 6 个精标专业

# 精标专业在报告里要单独处理，所以合成一个总索引
ALL_NAMES = sorted(list(MAJORS.keys()) + list(CURATED.keys()))


def is_curated(name):
    """这个专业是不是我们逐个访谈标注过的。"""
    return name in CURATED


def profile_of(name):
    return CURATED.get(name) or MAJORS.get(name)


def dims_of(name):
    p = profile_of(name)
    return p["dims"] if p else [3] * 7


def avoid_of(name):
    p = profile_of(name)
    return p["avoid"] if p else []


def ir_of(name):
    p = profile_of(name)
    return p["ir"] if p else None


def cost_of(name):
    p = profile_of(name)
    if not p:
        return None
    c = p["cost"]
    if isinstance(c, list):
        return {"hours": c[0], "years": c[1], "delay": c[2], "reversible": c[3], "note": ""}
    return {"hours": c.get("hours_per_week"), "years": c.get("years_to_competence"),
            "delay": c.get("feedback_delay_months"), "reversible": c.get("reversible"),
            "note": c.get("note", "")}


