ALLOWED_DOMAINS = {
    "potential", "transition", "autonomy", "vocation",     # 关于「你这个人」
    "feasibility", "cost", "optionality",                   # 关于「现实条件」
}
PERSONAL_DOMAINS = {"potential", "transition", "autonomy", "vocation"}

# 能力维度 → 影响哪几个需求维度，以及权重
ABILITY_TO_DEMAND = {
    "logic": [("cognitive", 1.0), ("memory", 0.6), ("failure_tolerance", 0.3)],
    "self_drive": [("self_drive", 1.0), ("long_feedback", 0.7)],
    "judgment": [("cognitive", 0.7), ("sensation", 0.5), ("failure_tolerance", 0.4)],
    "hands_on": [("hands_on", 1.0), ("sensation", 0.5)],
    "empathy": [("sensation", 0.5), ("failure_tolerance", 0.4)],
    "creativity": [("cognitive", 0.5), ("hands_on", 0.4)],
    "language": [("cognitive", 0.4), ("memory", 0.4)],
    "organization": [("memory", 0.3), ("self_drive", 0.4)],
}

# 每个需求维度在「潜质」里占多重。访谈里反复出现的一条是：
# 自驱和扛得住，比聪明更决定你能走多远，所以它们权重更高。
DIM_WEIGHT = [1.0, 0.7, 0.9, 0.9, 1.3, 1.2, 1.1]

# 你愿意为它付多少代价 —— 这一项直接给「可转换」分乘一个系数
WILLING_FACTOR = {1: 0.45, 2: 0.65, 3: 0.85, 4: 1.0, 5: 1.0}


def assert_personal_only(domain, source):
    """现实约束不许碰「关于你这个人」的判断。越界就报错。"""
    if domain in PERSONAL_DOMAINS:
        raise AssertionError(
            f"这里不该出现「{source}」：它是现实条件，只能影响可行性和时间表，"
            f"不能用来判断你这个人适合什么。"
        )


class Report:
    """一个专业的评估结果。注意它不叫「推荐」，叫「值得验证的假设」。"""

    def __init__(self, name):
        self.name = name
        self.curated = is_curated(name)
        self.scores = {}
        self.dims = []
        self.collisions = []      # 避雷碰撞
        self.notes = []
        self.warnings = []        # 资料可信度声明（必须显示出来）
        self.hypotheses = []      # 你身上的矛盾
        self.ii = None
        self.actions = []
        self.moves = []

    @property
    def total(self):
        s = self.scores
        return round(0.20 * s["potential"] + 0.20 * s["transition"]
                     + 0.25 * s["autonomy"] + 0.15 * s["feasibility"]
                     + 0.20 * s["vocation"], 3)


def score_potential(sig, name):
    """潜质 = 你现在做的事，和这个专业对人的要求，有多少对得上。"""
    needs = dims_of(name)
    got = []
    for i, need in enumerate(needs):
        num = den = 0.0
        for ab, maps in ABILITY_TO_DEMAND.items():
            for dim_idx, w in maps:
                if dim_idx != i:
                    continue
                num += sig[ab].score * w
                den += w
        have = num / den if den else 2.6
        got.append((need, have, DIM_WEIGHT[i]))

    num = sum(min(need, have) * w for need, have, w in got)   # 取 min：短板说了算
    den = sum(need * w for need, have, w in got)
    base = num / den if den else 0.5

    detail = {}
    for i, (need, have, _) in enumerate(got):
        detail[DEMAND_NAMES[i]] = min(1.0, have / need) if need else 1.0
    return round(base, 3), detail


def score_transition(sig, name, willing):
    """可转换 = 现在差多少，补起来要多久。**先过「你愿不愿意」这道门。**"""
    needs = dims_of(name)
    detail = []
    for i, need in enumerate(needs):
        w = willing.get(DEMAND_NAMES[i], 3)
        detail.append((DEMAND_NAMES[i], need, w, WILLING_FACTOR[w]))

    # 你根本不愿意付的代价，能力再高也补不上
    gate = sum(d[3] * d[1] for d in detail) / sum(d[1] for d in detail)
    base = min(1.0, gate * 1.15)

    # 慢反馈这一项如果要求高、你意愿低，额外扣一档。
    # 原因：它补不了。能力可以练，但「长时间看不到结果还能做下去」
    # 只能靠外部结构（固定时间、同伴、老师）接住。
    if needs[6] >= 4 and willing.get("慢反馈耐受", 3) <= 2:
        base *= 0.85
    return round(base, 3), detail


def check_avoid(name, avoid_list):
    """避雷前置筛选。注意：这里不做「不建议」，只做提示。"""
    zones = avoid_of(name)
    hits = []
    for tag, form in zones:
        if tag in avoid_list:
            hits.append({"tag": tag, "form": form})
    score = max(0.15, 1.0 - 0.22 * len(hits))
    return round(score, 3), hits


def score_feasibility(name, constraints):
    """可行性。注意这里是唯一允许读现实约束的地方。"""
    notes = []
    s = 1.0
    cost = cost_of(name) or {}
    if "经济压力" in constraints:
        s -= 0.18
        notes.append("经济压力会拖慢你，但它不该决定你去哪——"
                     "它决定的是路径和时间表。优先找有资助、能边做边赚的入口。")
    if "家庭期待" in constraints:
        s -= 0.10
        notes.append("家里的期待是真实存在的力量。别硬扛，也别被它替你决定。"
                     "把「我要做什么」和「怎么让家里放心」分成两个问题来解。")
    if "地域限制" in constraints:
        s -= 0.12
        notes.append("地域会限制你能接触到的人和机会。先看有没有线上可参与的部分。")
    if "成绩限制" in constraints:
        s -= 0.15
        notes.append("分数决定了入口，不决定终点。同一个方向上，路径往往不止一条。")
    if "健康" in constraints:
        s -= 0.20
        notes.append("身体是前提，不是条件。优先排除掉作息和体力消耗过高的方向。")
    if cost.get("reversible") is False:
        s -= 0.10
        notes.append("这条路**不太好回头**，进去之前多花点时间确认，是划算的。")
    if (cost.get("delay") or 0) >= 24:
        s -= 0.08
        notes.append(f"第一次明确反馈大约要等 {cost['delay']} 个月。"
                     "这段时间你需要自己给自己找阶段性的成就感。")
    return round(max(0.2, min(1.0, s)), 3), notes


def rarity_of(sig):
    """你的能力组合有多罕见。用信息熵算——越均匀越常见，越偏越少见。"""
    ps = [sig[k].confidence() for k in CUE_WORDS]
    ps = [p for p in ps if p > 0]
    if len(ps) < 2:
        return 0.0
    total = sum(ps)
    ps = [p / total for p in ps]
    ent = -sum(p * math.log(p) for p in ps)
    max_ent = math.log(len(ps))
    return round(max(0.0, min(1.0, 1 - ent / max_ent)) if max_ent else 0.0, 3)


def score_irreplaceable(sig, name):
    """不可替代性指数 II。四维 + 你的组合稀有度，上限 100。"""
    ir = ir_of(name)
    if not ir:
        return None
    p = profile_of(name)
    tilt = p.get("tilt", 0)
    base = sum(ir)                                   # 0—12
    rar = rarity_of(sig)
    mult = 1.0 + 0.3 * rar
    ii = round(min(100.0, max(0.0, (base + tilt) / 12.0) * 100 * mult), 1)

    weakest_i = ir.index(min(ir))
    return {
        "ii": ii, "base": base, "rarity": rar, "mult": round(mult, 3),
        "dims": dict(zip(IR_NAMES, ir)),
        "weakest": IR_NAMES[weakest_i],
        "weakest_detail": IR_DETAIL[IR_NAMES[weakest_i]],
        "ai_note": p.get("ai_note", ""),
        "bottleneck": p.get("bottleneck", ""),
        "provisional": not is_curated(name),
    }


def three_moves(sig, name, irinfo):
    """三条往「更不容易被替代」的方向挪的路。第三条最普适。"""
    if not irinfo:
        return []
    dims = irinfo["dims"]
    top = max(dims, key=lambda k: dims[k])
    route = {
        "要担责": ("往「要签字、要担责」的位置走",
                   "去拿那些有门槛、出了事要你负责的资格或角色。"
                   "这是 AI 最难取代的一层——它能给建议，但不承担后果。"),
        "手艺": ("往「靠手上功夫」的位置走",
                 "找那种必须亲手做够时间才有手感的部分。"
                 "这类东西写不进操作手册，也就进不了训练数据。"),
        "关系": ("往「人和人之间」的位置走",
                 "去那些别人愿意跟你说真话的场合。信任没法伪造。"),
        "判断": ("往「拿主意」的位置走",
                 "去那些信息不全、必须有人拍板的地方。这不是算出来的，是担出来的。"),
    }[top]

    strong = sorted(sig.items(), key=lambda kv: -kv[1].score)
    top2 = [ABILITY_NAMES[k] for k, _ in strong[:2]]

    return [
        {"name": f"① {route[0]}", "detail": route[1]},
        {"name": "② 把你的短板补到及格线以上",
         "detail": f"你现在最弱的是「{irinfo['weakest']}」。"
                   f"{irinfo['weakest_detail']}不用做到最好，做到不被它挡住就行。"},
        {"name": "③ 往「交叉点」走（这条最通用）",
         "detail": f"你比较强的两项是「{top2[0]}」和「{top2[1]}」。"
                   f"真正稀缺的往往不是某一行的第一名，而是两件事的交点。"
                   f"这个方向 + 你的另一项能力，组成的东西比单点拔尖更少见"
                   f"（你的组合稀有度是 {irinfo['rarity']}）。"},
    ]


def find_conflicts(r, sig, profile):
    """把矛盾摊开讲清楚。每一条后面都必须跟「那怎么办」。

    返回 (需要公示的警告, 矛盾清单)。
    这两类要分开：警告是「资料可信度」的说明，必须显示在标题旁边；
    矛盾是「你这个人身上的张力」，放在正文里讲。
    早先版本把两者塞在同一个列表里，结果报告层用 startswith("⚠️")
    过滤的时候，把「资料未核实」这个关键声明一起删掉了 ——
    等于产品最该说清的那句话被自己的排版逻辑吃掉了。
    """
    warnings = []
    out = []
    s = r.scores

    if not r.curated:
        warnings.append("这个专业的资料，是我们从旧数据推出来的，**没有经过访谈核实**。"
                        "下面这些先当成「一个方向」，别当成结论。")

    if s["potential"] < 0.55 and profile["motive_level"] in ("identified", "intrinsic"):
        out.append("你嘴上说想学它，但你的经历里还看不出相关的动作。"
                   "**这不算「你不适合」——这是「这条还没验证过」。** "
                   "去找一件四周能做完的小事，用做过什么来替代想过什么。")

    if s["potential"] > 0.72 and s["autonomy"] < 0.5:
        out.append("你在这件事上明显做得好，但你说选它的理由不太像你自己的。"
                   "先回答一个问题：**如果没有任何人知道你的选择，你还会选吗？**")

    if profile["motive_level"] == "introjected":
        out.append("你的话里出现了「应该」「不然」「光荣」这类词。"
                   "这种动机最容易被误当成热爱——它撑得住一阵子，撑不住很多年。"
                   "不是要你放弃，是请你把它换成自己的话再讲一遍。")

    if r.collisions:
        tags = "、".join(c["tag"] for c in r.collisions)
        out.append(f"你说你不想接受「{tags}」，而这恰好是这个方向的日常组成部分。"
                   f"**我们不劝你放弃**，但这一条要比其他任何一条优先验证。"
                   f"很多人的经验是：不讨厌，比最喜欢更靠得住。")

    if s["feasibility"] < 0.7:
        out.append("现实条件会拖慢你，但不会决定你去哪。"
                   "**我们不帮你改方向，只帮你改路径和时间表。**")

    if r.ii and r.ii["ii"] < 55:
        out.append(f"这个方向被 AI 压缩得比较多（不可替代性 {r.ii['ii']}），"
                   f"短板在「{r.ii['weakest']}」。"
                   f"这不是劝你别去，是说你要有意识地往责任更重的那一端挪。")

    if profile.get("counter"):
        out.append("你的叙述里出现了「做不下去 / 不喜欢」这类话。"
                   "**这不一定是能力问题。** 先分清是「真的不喜欢」，"
                   "还是「只是现在做得不好」。用「如果我已经做得很好了，我还愿意做吗」"
                   "来分——大多数人卡在后者。")

    return warnings, out


def evaluate(profile, allow_provisional=False):
    """跑一遍所有专业。默认只跑那 6 个访谈标注过的。

    为什么默认不开全量：88 个推导专业的资料是估的，
    把它们和真做过访谈的放一起排名，估的会盖过实的。
    这个坑我们真踩过一次，所以默认关掉，要看全量得自己点开。
    """
    pool = ALL_NAMES if allow_provisional else [n for n in ALL_NAMES if is_curated(n)]
    results = []
    sig = profile["sig"]

    for name in pool:
        r = Report(name)
        r.scores["potential"], r.dims = score_potential(sig, name)
        r.scores["transition"], _ = score_transition(sig, name, profile["willing"])
        r.scores["autonomy"] = profile["autonomy"]
        r.scores["feasibility"], r.notes = score_feasibility(name, profile["constraints"])
        r.scores["avoidance"], r.collisions = check_avoid(name, profile["avoid"])
        r.ii = score_irreplaceable(sig, name)
        r.scores["vocation"] = round((r.ii["ii"] / 100.0), 3) if r.ii else 0.0

        r.warnings, r.hypotheses = find_conflicts(r, sig, profile)
        r.moves = three_moves(sig, name, r.ii)

        # 缺口动作：把最弱的两维变成能马上做的事
        weak = sorted(r.dims.items(), key=lambda kv: kv[1])[:2]
        man = (profile_of(name) or {}).get("manifest") or {}
        acts = []
        for d, v in weak:
            if d in man:
                acts.append(f"「{d}」你现在对得上 {v:.0%}。这个专业里它长这样：{man[d]}。"
                            f"给自己安排一件四周能做完的小事，专门碰一碰它。")
            else:
                acts.append(f"「{d}」你现在对得上 {v:.0%}。这一项我们还没有访谈资料，"
                            f"建议你找一位在读学生或从业者问一句：这件事在你们那儿"
                            f"具体是什么样子？")
        old = (profile_of(name) or {}).get("act") or []
        r.actions = acts + [f"旧资料里建议的试法：{a}" for a in old[:3]]

        results.append(r)

    results.sort(key=lambda x: -x.total)
    return results



