def money_stars(n):
    return "●" * n + "○" * (3 - n)


def build_report(profile, results):
    sig = profile["sig"]
    L = []

    L.append("# 你的志业报告")
    L.append("")
    L.append("> 先说清楚三件事：")
    L.append("> 1. **这不是推荐。** 下面每一个专业都是一个「值得验证的假设」，"
             "不是一个答案。")
    L.append("> 2. **我们不会说你「不适合」。** 没验证过的，我们只说「待验证」。")
    L.append("> 3. **能力可以补，代价必须认。** 所以我们会花很多篇幅跟你算代价。")
    L.append("")

    # 结尾这几段是给「展开了 88 个未核实专业」的情况看的。
    # 排名前几的如果全是那 6 个访谈标注的，下面就没有未核实声明——
    # 那种情况下也必须说清「你看的范围里有一批是估的」，不能让人误以为全都可靠。
    _n_prov = sum(1 for r in results if not r.curated)
    if _n_prov:
        L.append(f"> ⚠️ **一个必须先说明的范围问题：** "
                 f"这次分析里 {_n_prov} 个专业的资料是从旧数据推出来的，"
                 f"**没有经过访谈核实**，只有 {len(results) - _n_prov} 个是我们真正访谈过的。"
                 f"凡是标了「资料未核实」的，请当成一个方向，别当成结论。")
        L.append("")

    # ---------- 一、我听到的你 ----------
    L.append("---")
    L.append("")
    L.append("## 一、我从你的话里听到的")
    L.append("")

    L.append("### 你做过什么（证据有多硬）")
    L.append("")
    L.append("这一栏的重点是**证据的可靠程度**，不是你的能力高低。")
    L.append("")
    L.append("| 能力 | 证据 | 状态 | 你自己说过的话 |")
    L.append("|---|---|---|---|")
    for k in CUE_WORDS:
        s = sig[k]
        q = s.quotes[0][:40] + "…" if s.quotes else "—"
        L.append(f"| {ABILITY_NAMES[k]} | {s.stars} | {s.status} | {q} |")
    L.append("")
    L.append("**图例**")
    L.append("")
    L.append("- ●●● 反复出现　●●○ 有经历支撑　●○○ 看到一点线索　○○○ 还没提到")
    L.append("")

    todo = [ABILITY_NAMES[k] for k in CUE_WORDS if sig[k].only_claim]
    if todo:
        L.append(f"**有一件事得说清楚：** 在「{'、'.join(todo)}」上，"
                 f"你目前只有自我形容，还没有具体例子。")
        L.append("")
        L.append("**这不代表你不行——只代表这条还没被验证过。** "
                 "自己说自己是什么样的人，那是一个宣言；讲清楚你做过什么动作，那才是证据。")
        L.append("")

    claims = [q for k in CUE_WORDS for q in sig[k].claims][:5]
    if claims:
        L.append("你对自己的一些判断（暂时都记作「待验证」）：")
        L.append("")
        for c in claims:
            L.append(f"- 「{c}」")
        L.append("")

    fl = flow_quotes(profile["narrative"])
    if fl:
        L.append("### 你说到「忘了时间」的地方")
        L.append("")
        L.append("这是最值钱的一类线索——因为它不靠意志力，它自己会拉你走。")
        L.append("")
        for q in fl[:3]:
            L.append(f"> {q}")
        L.append("")

    if sig["logic"].counter or any(sig[k].counter for k in CUE_WORDS):
        cnt = []
        for k in CUE_WORDS:
            cnt += sig[k].counter
        L.append("### 你自己提到「做不下去」的地方")
        L.append("")
        for q in cnt[:3]:
            L.append(f"> {q}")
        L.append("")
        L.append("**先别急着把它当成「我不适合」。** 这里有一个很重要的区分："
                 "是真的不喜欢，还是只是现在做得不好？")
        L.append("")
        L.append("> 问自己一句：**如果这件事我已经做得很好了，我还愿意做吗？**")
        L.append("")

    th = profile["themes"]
    if th:
        L.append(f"**我隐约看到的线索**：{'、'.join(th)}")
        L.append("")
        L.append("（这是机器从你的用词里读出来的，不一定对。你自己判断。）")
        L.append("")

    L.append("### 你选它的理由，是谁的理由")
    L.append("")
