# ==================================================================
# 【附】DeepSeek 润色（可选，不填 Key 就不走这一步）
# ==================================================================
# 用不用 LLM 都行。但这里有一条必须守住的规矩，所以写在 prompt 里：
#
#   **不许把「待验证」改写成「不擅长」。**
#
# 因为语言模型最爱干的就是这种「善意」的平滑处理。而那一改，
# 整个产品最核心的那句话就没了。
# ==================================================================

POLISH_RULES = """你是一位温和、有洞察力的生涯陪跑老师，正在跟一位为专业选择发愁的大学生说话。

【绝对不能做】
1. 不许新增任何事实。专业要求、代价数字、不可替代性分数，一律原样保留。
2. 不许把「待验证」「还没提到」「只看到一点线索」改成「不擅长」「能力弱」「缺乏」。
   证据不足只说明这条还没被验证，不说明这个人不行。这是本产品的底线。
3. 不许新增「你应该选 X」「建议你选 X」这类结论。我们不做推荐。
4. 不许删除或削弱任何标记：●●○ 这类符号、⚠️ 警告、「资料未核实」、
   避雷碰撞、矛盾清单、来源标注，全部保留。
5. 不许改任何数字。
6. 保留全部 Markdown 结构（标题、表格、列表、引用）。

【要做到】
- 用「你」称呼学生，说人话，别端着
- 不要用「综上所述」「赋能」「打造」「助力」这类词
- 遇到坏消息，先说「那怎么办」，再说结论
- 在开头加两三句「我听到的你」，概括这个人的状态，但只能基于原文已有的信息
- 结尾鼓励一句，但别灌鸡汤，别承诺"""


def polish(report, api_key):
    """调用 DeepSeek 润色。出任何问题都原样返回，绝不丢内容。"""
    try:
        from openai import OpenAI
    except ImportError:
        st.warning("没装 openai 库，跳过润色。想用就 `pip install openai`。")
        return report

    try:
        client = OpenAI(api_key=api_key, base_url="https://api.deepseek.com")
        resp = client.chat.completions.create(
            model="deepseek-chat",
            messages=[{"role": "system", "content": POLISH_RULES},
                      {"role": "user", "content":
                       "把下面这份报告改写得更有人味。只改语言，不改内容和结构。\n\n"
                       + report}],
            temperature=0.7, max_tokens=4000,
        )
        out = resp.choices[0].message.content

        # 后置检查：模型如果违反了规矩，就丢掉它的输出，用原文。
        # 宁可不要润色，也不能让立场被悄悄改坏。
        bad = []
        for w in ("你应该选", "建议你选", "不适合你", "能力不足", "你缺乏"):
            if w in out and w not in report:
                bad.append(w)
        for mark in ("●●●", "●●○", "●○○", "○○○"):
            if report.count(mark) > out.count(mark):
                bad.append(f"证据标记 {mark} 丢了")
        if bad:
            st.warning("润色结果违反了产品底线，已丢弃并保留原报告。触发项："
                       + "；".join(sorted(set(bad))))
            return report
        return out

    except Exception as e:
        st.warning(f"调用失败，已保留原报告：{e}")
        return report


